use vstd::prelude::*;
use vstd::{vec, Vec};

verus! {

fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> (result: Vec<f32>)
    requires
        a.len() == mask.len(),
        values.len() > 0,
    ensures
        result.len() == a.len(),
        forall(|i: usize| i < a.len() ==>
            if mask[i] {
                // output at i is from values at i mod values.len()
                result[i] == values[i % values.len()]
                // and this value is indeed contained in values
                && values.contains(result[i])
            } else {
                // if mask false, output == input
                result[i] == a[i]
            }
        ),
{
    let n = a.len();
    let vlen = values.len();
    let mut res = Vec::empty();

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            res.len() == i,
            forall(|j: usize| j < i ==>
                if mask[j] {
                    res[j] == values[j % vlen] && values.contains(res[j])
                } else {
                    res[j] == a[j]
                }
            ),
    {
        let val = if mask[i] {
            values[i % vlen]
        } else {
            a[i]
        };
        res.push(val);
        i += 1;
    }

    res
}

}